exercises.solution:
import hashlib

def alteres(fichiers, manifeste):
    resultat = []
    for nom, empreinte in manifeste.items():
        if nom not in fichiers:
            resultat.append(nom)
        elif hashlib.sha256(fichiers[nom].encode("utf-8")).hexdigest() != empreinte:
            resultat.append(nom)
    return sorted(resultat)

import hashlib

def rapport_integrite(fichiers, manifeste):
    r = {"intacts": [], "modifiés": [], "manquants": [], "nouveaux": []}
    for nom, empreinte in manifeste.items():
        if nom not in fichiers:
            r["manquants"].append(nom)
        elif hashlib.sha256(fichiers[nom].encode("utf-8")).hexdigest() == empreinte:
            r["intacts"].append(nom)
        else:
            r["modifiés"].append(nom)
    for nom in fichiers:
        if nom not in manifeste:
            r["nouveaux"].append(nom)
    for liste in r.values():
        liste.sort()
    return r
